DELETE FROM Language_en_US WHERE Tag='TXT_KEY_CWC_GUIDE_FILTHYREALM' OR Tag GLOB 'TXT_KEY_CWC_GUIDE_FILTHYREALM_*';
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_FILTHYREALM_CIV_HEADING_1','Playstyle and victory plan');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_FILTHYREALM_CIV_TEXT_1','The Filthy Realm[NEWLINE]Foreign-city disruption and timed active control[NEWLINE]Culture with military pressure; Domination as an alternative[NEWLINE][NEWLINE]Maintain foreign contact to build Filth, earn Filthy Points, and spend them where a temporary disruption changes the next battle or construction race. Contact and a usable treasury of points matter more than the size of a single debuff.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_FILTHYREALM_CIV_HEADING_2','Opening priorities');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_FILTHYREALM_CIV_TEXT_2','Develop a normal cultural economy and identify reachable foreign cities. Maintain safe trade and useful contacts without treating contamination as an immediate army replacement. Build points before planning an expensive active ability.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_FILTHYREALM_CIV_HEADING_3','Develop the engine');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_FILTHYREALM_CIV_TEXT_3','Keep selected targets connected to your pressure so Filth does not simply decay. Use the panel to check valid targets and cooldowns. Match theft, Distortion or Salamander support to a real local objective.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_FILTHYREALM_CIV_HEADING_4','Convert the advantage');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_FILTHYREALM_CIV_TEXT_4','Coordinate It''s Time to Stop with your army''s position and a decisive turn. Peace Lords and Kitchens strengthen the later loop, but overcommitting to one target can leave your own economy and other fronts exposed.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_FILTHYREALM_CIV_HEADING_5','Strengths');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_FILTHYREALM_CIV_TEXT_5','- Several forms of contact can sustain pressure on important foreign cities.[NEWLINE]- A shared ability currency allows economic interference or tactical support.[NEWLINE]- Late cultural infrastructure supports both Tourism and point generation.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_FILTHYREALM_CIV_HEADING_6','Weaknesses and costs');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_FILTHYREALM_CIV_TEXT_6','- Contamination takes time and can decay without continued contact.[NEWLINE]- Abilities have real costs, range/eligibility rules and cooldowns.[NEWLINE]- Economic penalties and a one-turn shutdown do not replace an army capable of exploiting them.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_FILTHYREALM_CIV_HEADING_7','How to play against this civilization');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_FILTHYREALM_CIV_TEXT_7','- Reduce avoidable foreign trade exposure and remove hostile units maintaining pressure.[NEWLINE]- Force Frank to spend points defensively or divide attention among targets.[NEWLINE]- Avoid leaving an entire attack force in range of a single decisive shutdown.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_FILTHYREALM_CIV_HEADING_8','Common mistakes');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_FILTHYREALM_CIV_TEXT_8','- Assuming Filth remains indefinitely after all contact ends.[NEWLINE]- Using a costly control ability before friendly units can capitalize.[NEWLINE]- Spending points without checking the selected target and cooldown.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_FILTHYREALM_CIV_HEADING_9','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_FILTHYREALM_CIV_TEXT_9','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]Sol Intellect: Yield and Production disruption pressures a civilization that depends on protected construction and research cities.[NEWLINE][NEWLINE]RomanGladius Network: Pressure on a major population centre can undermine the growth and Gold needed to maintain a healthy Server network.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]The Urgal: An early coordinated attack can arrive before a useful contamination network and point reserve are established.[NEWLINE][NEWLINE]Pigeon Republic: Safe domestic caravans can supply Coo''s ability without providing the easy foreign trade connection Frank would prefer; tourism or military contact can still spread Filth.');
