INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_FILTHYREALM_STRATEGY','Maintain foreign contact to build Filth, earn Filthy Points, and spend them where a temporary disruption changes the next battle or construction race. Contact and a usable treasury of points matter more than the size of a single debuff.[NEWLINE][NEWLINE]Develop a normal cultural economy and identify reachable foreign cities. Maintain safe trade and useful contacts without treating contamination as an immediate army replacement. Build points before planning an expensive active ability.[NEWLINE][NEWLINE]Keep selected targets connected to your pressure so Filth does not simply decay. Use the panel to check valid targets and cooldowns. Match theft, Distortion or Salamander support to a real local objective.[NEWLINE][NEWLINE]Coordinate It''s Time to Stop with your army''s position and a decisive turn. Peace Lords and Kitchens strengthen the later loop, but overcommitting to one target can leave your own economy and other fronts exposed.');
