INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_FILTHYREALM_LEADER_HEADING_2','Priorities and decisions');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_FILTHYREALM_LEADER_TEXT_2','Develop a normal cultural economy and identify reachable foreign cities. Maintain safe trade and useful contacts without treating contamination as an immediate army replacement. Build points before planning an expensive active ability.[NEWLINE][NEWLINE]Keep selected targets connected to your pressure so Filth does not simply decay. Use the panel to check valid targets and cooldowns. Match theft, Distortion or Salamander support to a real local objective.[NEWLINE][NEWLINE]Coordinate It''s Time to Stop with your army''s position and a decisive turn. Peace Lords and Kitchens strengthen the later loop, but overcommitting to one target can leave your own economy and other fronts exposed.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_FILTHYREALM_LEADER_HEADING_3','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_FILTHYREALM_LEADER_TEXT_3','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]Sol Intellect: Yield and Production disruption pressures a civilization that depends on protected construction and research cities.[NEWLINE][NEWLINE]RomanGladius Network: Pressure on a major population centre can undermine the growth and Gold needed to maintain a healthy Server network.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]The Urgal: An early coordinated attack can arrive before a useful contamination network and point reserve are established.[NEWLINE][NEWLINE]Pigeon Republic: Safe domestic caravans can supply Coo''s ability without providing the easy foreign trade connection Frank would prefer; tourism or military contact can still spread Filth.');
